:root { --bg: #f4ecd8; --ink: #2b2b2b; --card: #ffffff; --accent: #ff7a5a; --accent-2: #58a4ff; --radius: 20px; --lip: 8px; }html, body { margin: 0px; min-height: 100vh; text-size-adjust: 100%; }body { font-family: system-ui, sans-serif; background-position-x: ; background-position-y: ; background-size: ; background-repeat: ; background-attachment: ; background-origin: ; background-clip: ; background-color: ; background-image: radial-gradient(circle at 20% 10%, color-mix(in srgb, var(--accent) 30%, transparent) 0, transparent 40%),
        radial-gradient(circle at 80% 90%, color-mix(in srgb, var(--accent-2) 25%, transparent) 0, transparent 45%); display: grid; place-items: center; padding: 2rem; box-sizing: border-box; color: var(--ink); }main { text-align: center; max-width: 36rem; }h1 { font: 900 3rem / 1.05 system-ui, sans-serif; letter-spacing: -0.02em; margin: 0px 0px 0.25rem; }h1 .wave { display: inline-block; transform-origin: 70% 70%; animation: 1.6s ease 0s infinite normal none running wave; }@keyframes wave { 
  0%, 100% { transform: rotate(0deg); }
  25% { transform: rotate(20deg); }
  75% { transform: rotate(-10deg); }
}.lead { font-size: 1.2rem; margin: 0.75rem 0px 1.25rem; }.prompts-label { margin: 0px 0px 0.75rem; font-size: 1rem; opacity: 0.8; }.panel { display: flex; flex-direction: column; gap: 0.85rem; background: color-mix(in srgb, var(--card) 70%, transparent); padding: 1.25rem; border-radius: var(--radius); text-align: left; box-shadow: 0 var(--lip) 0 color-mix(in srgb, var(--ink) 12%, transparent); }.prompt { display: flex; align-items: center; gap: 0.85rem; background: var(--card); padding: 0.75rem 1rem; border-radius: 14px; box-shadow: 0 4px 0 color-mix(in srgb, var(--ink) 10%, transparent); }.pic { font-size: 1.8rem; flex-shrink: 0; width: 2.5rem; text-align: center; line-height: 1; }code { background: transparent; padding: 0px; font-family: ui-monospace, monospace; font-size: 0.95rem; line-height: 1.4; }footer { margin-top: 1.5rem; opacity: 0.55; font-size: 0.9rem; }

